package com.queuecraft.model;
import java.util.Objects;
public final class Customer {
 private final long id; private final String displayName; private final ServiceType requestedService; private final long arrivalTick; private CustomerStatus status=CustomerStatus.WAITING; private long serviceStartTick=-1, completionTick=-1;
 public Customer(long id,String displayName,ServiceType service,long arrivalTick){if(id<1||arrivalTick<0)throw new IllegalArgumentException("ID must be positive and tick nonnegative.");this.id=id;this.displayName=Objects.requireNonNull(displayName);this.requestedService=Objects.requireNonNull(service);this.arrivalTick=arrivalTick;}
 public void startService(long tick){if(status!=CustomerStatus.WAITING)throw new IllegalStateException("Only waiting customers can start service.");if(tick<arrivalTick)throw new IllegalArgumentException("Service cannot precede arrival.");serviceStartTick=tick;status=CustomerStatus.BEING_SERVED;}
 public void complete(long tick){if(status!=CustomerStatus.BEING_SERVED)throw new IllegalStateException("Only active customers can complete.");if(tick<serviceStartTick)throw new IllegalArgumentException("Completion precedes service start.");completionTick=tick;status=CustomerStatus.COMPLETED;}
 public long getId(){return id;} public String getDisplayName(){return displayName;} public ServiceType getRequestedService(){return requestedService;} public long getArrivalTick(){return arrivalTick;} public CustomerStatus getStatus(){return status;} public long getServiceStartTick(){return serviceStartTick;} public long getCompletionTick(){return completionTick;} public long getWaitingTime(){return serviceStartTick<0?0:serviceStartTick-arrivalTick;} public long getServiceDuration(){return completionTick<0?0:completionTick-serviceStartTick;}
}
